#!/usr/bin/env python3
"""Freeze the observed complete-core calibration scope, without fitting cycles."""
from pathlib import Path
import argparse,datetime,hashlib,json
S=Path(__file__).resolve().parent;ROOT=S.parents[3]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('baseline',type=Path);ap.add_argument('stress',type=Path);ap.add_argument('comparison',type=Path);ap.add_argument('rtl',type=Path);ap.add_argument('output',type=Path);a=ap.parse_args();a.output.mkdir(parents=True,exist_ok=False)
 comparison={n:json.loads((a.comparison/(n+'.json')).read_text())for n in ['d3','d4','d4_stress']};bindings={n:json.loads((p/'binding.json').read_text())for n,p in [('base',a.baseline),('stress',a.stress)]};assert bindings['base']['binary_sha256']==bindings['stress']['binary_sha256']
 assert all(x['all_outputs_exact']and x['all_counter_totals_exact']and x['all_request_kinds_exact']for x in comparison.values())
 samples=[x for c in comparison.values()for x in c['samples']];assert len(samples)==32
 phase_ranges={}
 for row in samples:
  for phase,x in row['phases'].items():
   d=phase_ranges.setdefault(phase,{'min_delta':x['delta'],'max_delta':x['delta'],'different_samples':0});d['min_delta']=min(d['min_delta'],x['delta']);d['max_delta']=max(d['max_delta'],x['delta']);d['different_samples']+=x['delta']!=0
 exact_schedule=sum(x['logical_request_schedule_exact']for x in samples)
 result={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'VERIFIED_WITH_DECLARED_SCOPE','model_binary_sha256':bindings['base']['binary_sha256'],'model_source_sha256':bindings['base']['source_sha256'],'model_binding_sha256':{n:sha(p/'binding.json')for n,p in [('base',a.baseline),('stress',a.stress)]},'rtl_terminal_sha256':sha(a.rtl/'terminal.json'),'rtl_binding_sha256':sha(a.rtl/'binding.json'),'comparison_sha256':{n:sha(a.comparison/(n+'.json'))for n in comparison},'production_configuration':{'lanes':64,'groups':16,'T':128,'D':128,'ready':128,'target':128,'E':256,'beat':512,'K_per_bank':8,'banks':64,'physical_ports':32,'credits_per_port':32,'directory_members_per_bank':8192},'memory':{'frequency_mhz':200,'latency_ns':80,'issue_interval_ns':5,'latency_cycles':16,'issue_cycles':1,'stress_jitter_cycles':'(tag*7+port*3)%17','stress_issue_gate':'(absolute_memory_edge+port)%19 < 14','sample_clock':'continuous; initial jobs+2, then cumulative modeled sample cycles','physical_response_selection':'newest eligible request, held until handshake','evidence_type':'declared testbench service; not measured HBM'},'verified_samples':32,'graphs':{'native_d3_w8':{'base':8},'native_d4_w8':{'base':12,'stress':12}},'all_outputs_byte_exact':True,'all_request_kinds_and_retirement_counts_exact':True,'exact_logical_request_schedule_samples':exact_schedule,'phase_delta_observations':phase_ranges,'maximum_absolute_cycle_delta':max(abs(x['delta_cycles'])for x in samples),'maximum_absolute_relative_delta':max(abs(x['relative_delta'])for x in samples),'maximum_non_init_relative_delta':max(abs(x['non_init_relative_delta'])for x in samples),'calibration_scope':'complete deployed-parameter core on the two actual native small graphs, including one complete congested/stalled batch; explicit model services; comparison not formal equivalence','cycle_exact_all_samples':all(x['delta_cycles']==0 for x in samples),'no_empirical_correction':True,'known_model_approximation':'The inherited model visits metadata/front/scratch/canonical services in rotor%4 order with explicit due-edge guards, rather than evaluating every RTL process from one immutable whole-design pre-edge snapshot. Some equal-edge grants/request ordering can differ. Periodic external gates propagate a prior sample cycle difference into later sample service phases. Each sample/phase/request mismatch is retained.','limitations':['Observed errors apply only to these32 complete small-graph executions; they are not a universal error bound for BNN/LSTM.','Small graphs do not cover all production directory/scratch capacities; reuse the independent source-bound local capacity/protocol tests separately.','A changed RTL, topology, capacity, pipeline or external service contract requires revalidation; do not reuse this receipt by filename alone.','No routed clock or full40 performance claim is supplied by this subtask.'],'full40_launched':False,'full_core_routed_clock_verified':False,'qualified_clock_mhz':None,'board_measured':False}
 (a.output/'calibration_contract.json').write_text(json.dumps(result,indent=2)+'\n')
 lines=['# CPU-primary model calibration handoff','',f"Frozen binary: `{result['model_binary_sha256']}`.",'', 'Both complete native graphs (8+12 samples) and the12-sample stalled d4 batch pass: all32 complete outputs,12 request-kind totals, parent/candidate/commit/event/retirement counts agree with independent complete-core RTL. No cycle correction factor was used.','', '| Comparison | Samples | Maximum absolute cycle difference | Maximum relative total difference | Maximum difference after excluding INIT |','|---|---:|---:|---:|---:|']
 for n,c in comparison.items():lines.append(f"| {n} | {c['completed_samples']} | {c['maximum_absolute_cycle_delta']} | {100*c['maximum_absolute_relative_delta']:.6f}% | {100*c['maximum_non_init_relative_delta']:.6f}% |")
 lines+=['',f"Full logical request schedules (edge/source/kind/address/localID/generation) match for{exact_schedule}/32 samples. Per-phase and first request differences are preserved in the comparison JSON; a close total alone is not the calibration criterion.",'','The retained source follows the actual reset and ownership edges: dispatcher rotor starts at zero on SRST; a released member cannot schedule RELEASE on the same edge. These choices are based on RTL semantics, not selecting the version with the smallest net error. Earlier B/C/D/E snapshots remain available.','',result['known_model_approximation'],'','The error ranges above are observations on these fixtures, not guaranteed bounds for the full workloads. The original finite capacity checks and prior local service evidence remain necessary. Frequency qualification and full40 execution belong to the next coordinator stage; no full40 batch was started.','', 'Artifacts: `phase_trace.csv`, `core_phases.json`, `finite.json`, `events.csv`, complete `output.bin`, per-sample receipt, compile closure/binary/compiler and input/golden bindings. Source and raw outputs remain in this independent CPU_PRIMARY worktree.']
 (a.output/'SUMMARY.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({k:result[k]for k in ['status','verified_samples','maximum_absolute_cycle_delta','maximum_absolute_relative_delta','maximum_non_init_relative_delta','exact_logical_request_schedule_samples','cycle_exact_all_samples','full40_launched']},indent=2))
if __name__=='__main__':main()
